function admin_logs_date_where(string $column,array &$where,array &$params,string $from,string $to):void{
    if($from!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]="$column>=?";$params[]=$from.' 00:00:00';}
    if($to!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]="$column<=?";$params[]=$to.' 23:59:59';}
}
function admin_logs_csv_cell(mixed $value): string{
    $text=(string)$value;
    return preg_match('/^[=+\-@\t\r]/u',$text) ? "'".$text : $text;
}
function admin_logs_csv(string $filename,array $headers,array $rows):never{
    header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,array_map('admin_logs_csv_cell',$headers));foreach($rows as $row)fputcsv($out,array_map('admin_logs_csv_cell',$row));fclose($out);exit;
}
function admin_logs_query_string(array $changes=[]):string{$data=array_merge($_GET,$changes);foreach($data as $k=>$v)if($v===''||$v===null)unset($data[$k]);return http_build_query($data,'','&',PHP_QUERY_RFC3986);}
function admin_logs_result_label(string $v):string{return ['success'=>'成功','error'=>'错误','denied'=>'已阻止','failure'=>'失败','locked'=>'锁定','blocked'=>'限流','ignored'=>'忽略','active'=>'在线','revoked'=>'已撤销','expired'=>'已过期'][$v]??$v;}

