    $stats=['24h'=>(int)$pdo->query("SELECT (SELECT COUNT(*) FROM web_audit_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR))+(SELECT COUNT(*) FROM web_admin_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR))")->fetchColumn(),'errors'=>(int)$pdo->query("SELECT COUNT(*) FROM web_audit_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) AND result IN ('error','denied')")->fetchColumn(),'users'=>(int)$pdo->query("SELECT COUNT(DISTINCT user_id) FROM web_audit_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) AND user_id IS NOT NULL")->fetchColumn(),'total'=>$total];
    if(!empty($_GET['export'])){web_admin_require_permission($pdo,$user,'logs.export');$sql="SELECT x.*,COALESCE(u.display_name,u.username,x.username_snapshot,'系统') actor FROM ({$union}) x LEFT JOIN web_admin_users u ON u.id=x.user_id WHERE {$whereSql} ORDER BY x.created_at DESC,x.source_id DESC LIMIT 10000";$stmt=$pdo->prepare($sql);$stmt->execute($params);$export=$stmt->fetchAll();web_audit_log($pdo,(int)$user['id'],'logs.export','logs','log_source','actions','导出操作日志',null,null,['rows'=>count($export),'filters'=>web_admin_sanitize($_GET)]);admin_logs_csv('artdon-actions-'.date('Ymd-His').'.csv',['时间','用户','操作','模块','对象','结果','级别','IP','页面','摘要'],array_map(fn($r)=>[$r['created_at'],$r['actor'],admin_action_label((string)$r['action']),$r['module'],trim($r['target_type'].' '.$r['target_key']),admin_logs_result_label((string)$r['result']),$r['severity'],$r['ip_address'],$r['route'],$r['summary']],$export));}
