<?php elseif($tab==='sync'):?><tr><td><?= web_e($r['created_at']) ?></td><td><?= web_e(admin_status_label((string)$r['direction'])) ?></td><td><strong><?= web_e(admin_event_label((string)$r['event_type'])) ?></strong><small class="logs-code"><?= web_e($r['event_type']) ?></small></td><td><span class="status-badge is-<?= $r['result']==='error'?'danger':'success' ?>"><?= web_e(admin_logs_result_label((string)$r['result'])) ?></span></td><td><?= web_e($r['http_status']??'—') ?></td><td><?= web_e($r['message']) ?></td><td><a href="log_detail.php?source=sync&id=<?= (int)$r['id'] ?>">详情</a></td></tr>
<?php else:$state=!empty($r['revoked_at'])?'revoked':(strtotime((string)$r['expires_at'])<=time()?'expired':'active');?><tr><td><strong><?= web_e($r['actor']) ?></strong><small class="logs-code"><?= web_e($r['username']??'') ?></small></td><td><span class="status-badge is-<?= $state==='active'?'success':'muted' ?>"><?= web_e(admin_logs_result_label($state)) ?></span></td><td><?= web_e($r['ip_address']) ?></td><td class="security-ua"><?= web_e($r['user_agent']) ?></td><td><?= web_e($r['last_seen_at']) ?></td><td><?= web_e($r['expires_at']) ?></td><td><a href="log_detail.php?source=session&id=<?= (int)$r['id'] ?>">详情</a></td></tr><?php endif;?>
<?php endforeach;?></tbody></table></div><?php endif;?><?php if($pages>1):?><nav class="security-pagination"><?php for($i=max(1,$page-3);$i<=min($pages,$page+3);$i++):?><a class="<?= $i===$page?'is-active':'' ?>" href="?<?= web_e(admin_logs_query_string(['page'=>$i,'export'=>null])) ?>"><?= $i ?></a><?php endfor;?></nav><?php endif;?></section>
</div>
<?php if(web_admin_user_can($user,'logs.cleanup')):?><div class="security-modal" data-log-cleanup hidden><button class="security-modal-backdrop" type="button" data-log-cleanup-close></button><section><header><div><span class="security-eyebrow">Retention</span><h2>清理历史日志</h2></div><button type="button" data-log-cleanup-close>×</button></header><form method="post" data-confirm="日志清理后无法恢复，确定继续？"><input type="hidden" name="csrf" value="<?= web_e(web_csrf_token()) ?>"><div class="field"><label>清理范围</label><select name="source"><option value="<?= web_e($tab) ?>">当前模块</option><option value="all">全部日志</option></select></div><div class="field"><label>保留最近</label><select name="days"><option value="90">90 天</option><option value="180" selected>180 天</option><option value="365">365 天</option><option value="730">730 天</option></select></div><p>只删除超过保留期的历史记录；在线会话不会被删除。</p><footer><button class="admin-button-secondary" type="button" data-log-cleanup-close>取消</button><button class="admin-button is-danger" type="submit">确认清理</button></footer></form></section></div><?php endif;?>
